def odds(procs: int, metric: int, night_i: int, fill_i: int, raw_i: int) -> float:
    """The stored share (0..1) at one grid cell."""
    i = (
        (((procs - 1) * METRICS + metric) * 22 + night_i)
        * 14 + fill_i
    ) * 49 + raw_i
    return _DATA[i] / SCALE
